public String getHostAddress() throws UnknownHostException {
  if (hostAddress == null) {
    try {
      ClusterTask task = getRemoteSessionTask(RemoteSessionTask.Operation.getHostAddress);
      hostAddress = (String) doSynchronousClusterTask(task);
    } catch (NullPointerException e) {
      throw new RuntimeException("Failed to retrieve remote session task", e);
    } catch (ClassCastException e) {
      throw new RuntimeException("Unexpected return type from cluster task", e);
    }
  }
  return hostAddress;
}
